     1	import { useCallback, useEffect, useRef, useState } from 'react';
     2	
     3	const FOCUSABLE = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';
     4	
     5	type UseSubscribeModalParams = {
     6	  /** Whether the dialog is currently open. */
     7	  isOpen: boolean;
     8	  /** Called when the dialog should close (Escape). */
     9	  onClose: () => void;
    10	};
    11	
    12	type UseSubscribeModalReturn = {
    13	  /** False until after the first client render, so the portal is not created during SSR. */
    14	  mounted: boolean;
    15	  /** Attach to the dialog's <form> — bounds the Tab trap. */
    16	  formRef: React.RefObject<HTMLFormElement>;
    17	  /** Attach to the wrapper around the first field — its <input> receives initial focus. */
    18	  firstFocusRef: React.RefObject<HTMLDivElement>;
    19	};
    20	
    21	/**
    22	 * Dialog mechanics for the footer's subscribe modal: mount gating, focus save/restore,
    23	 * body-scroll lock, and the Escape/Tab keyboard trap.
    24	 *
    25	 * Extracted from SubscribeModal per components.md's extract-to-hook threshold — four effects,
    26	 * three of them with cleanup functions. None of it touches JSX, so the component keeps only its
    27	 * markup and the recipe lookup. Behaviour is unchanged; the effect order and dependency arrays
    28	 * are preserved exactly, because focus restore depends on running after the open-effect's
    29	 * cleanup.
    30	 *
    31	 * @param params isOpen and the close callback
    32	 * @returns the mount flag plus the two refs the dialog markup has to attach
    33	 */
    34	export const useSubscribeModal = ({ isOpen, onClose }: UseSubscribeModalParams): UseSubscribeModalReturn => {
    35	  const [mounted, setMounted] = useState(false);
    36	  const formRef = useRef<HTMLFormElement>(null);
    37	  const firstFocusRef = useRef<HTMLDivElement>(null);
    38	  const triggerRef = useRef<Element | null>(null);
    39	
    40	  useEffect(() => {
    41	    setMounted(true);
    42	  }, []);
    43	
    44	  // Save the trigger element on open so focus can be restored on close
    45	  useEffect(() => {
    46	    if (isOpen) {
    47	      triggerRef.current = document.activeElement;
    48	      // Defer so the portal has rendered before we try to focus inside it
    49	      const id = setTimeout(() => {
    50	        const firstInput = firstFocusRef.current?.querySelector<HTMLElement>('input');
    51	        firstInput?.focus();
    52	      }, 0);
    53	      return () => clearTimeout(id);
    54	    } else {
    55	      // Return focus to the element that opened the modal
    56	      if (triggerRef.current instanceof HTMLElement) {
    57	        triggerRef.current.focus();
    58	      }
    59	    }
    60	  }, [isOpen]);
    61	
    62	  // Lock body scroll while modal is open
    63	  useEffect(() => {
    64	    if (!isOpen) return;
    65	    const prev = document.body.style.overflow;
    66	    document.body.style.overflow = 'hidden';
    67	    return () => {
    68	      document.body.style.overflow = prev;
    69	    };
    70	  }, [isOpen]);
    71	
    72	  // Keyboard: Escape to close, Tab trap within modal
    73	  const handleKeyDown = useCallback(
    74	    (e: KeyboardEvent) => {
    75	      if (e.key === 'Escape') {
    76	        onClose();
    77	        return;
    78	      }
    79	      if (e.key !== 'Tab' || !formRef.current) return;
    80	
    81	      const focusable = Array.from(formRef.current.querySelectorAll<HTMLElement>(FOCUSABLE)).filter(
    82	        (el) => !el.hasAttribute('disabled'),
    83	      );
    84	
    85	      const first = focusable[0];
    86	      const last = focusable[focusable.length - 1];
    87	
    88	      if (e.shiftKey && document.activeElement === first) {
    89	        e.preventDefault();
    90	        last?.focus();
    91	      } else if (!e.shiftKey && document.activeElement === last) {
    92	        e.preventDefault();
    93	        first?.focus();
    94	      }
    95	    },
    96	    [onClose],
    97	  );
    98	
    99	  useEffect(() => {
   100	    if (!isOpen) return;
   101	    document.addEventListener('keydown', handleKeyDown);
   102	    return () => document.removeEventListener('keydown', handleKeyDown);
   103	  }, [isOpen, handleKeyDown]);
   104	
   105	  return { mounted, formRef, firstFocusRef };
   106	};

