454	              {navGroups.map((group) => (
455	                <chakra.div key={group.sys.id} __css={styles.linkCol}>
456	                  {/* Figma section column: flex-col gap-16px — the column gap replaces
457	                                        marginBottom on the heading. Contact heading has 4px left offset. */}
458	                  <chakra.p
459	                    __css={{
460	                      ...styles.columnHeading,
461	                      ...(group.fields.showContactChannels ? { paddingLeft: '2xs' } : {}),
462	                    }}
463	                  >
