    39	        aria-current={active ? 'page' : undefined}
    40	        onClick={onClick}
    41	        __css={styles}
    42	        sx={sx}
    43	        style={style}
    44	      >
    45	        <span>{label}</span>
    46	      </chakra.a>
    47	    );
    48	  }
    49	
    50	  return (
    51	    <chakra.button
    52	      type="button"
    53	      aria-current={active ? 'page' : undefined}
    54	      onClick={onClick}
    55	      __css={styles}
