     6	type ZimmTextInputProps = {
     7	  label: string;
     8	  type?: string;
     9	  name?: string;
    10	  inverse?: boolean;
    11	  disabled?: boolean;
    12	  helperText?: string;
    13	  errorText?: string;
    14	  onChange?: (value: string) => void;
    15	  /** Controlled value — pass with `onChange` to let a parent form own the value. */
    16	  value?: string;
    17	  /** Initial value when uncontrolled. Ignored if `value` is provided. */
    18	  defaultValue?: string;
    19	  /**
    20	   * Opt in to the clear-✕ shown once the field has a value. Defaults to false.
    21	   *
    22	   * Not in the design system: the extracted TextfieldV2 spec defines a `trailing-icon`
    23	   * attribute and no `clearable` attribute, and SFCC-55's AC specifies the Stay in Touch
    24	   * section as "an email input field and submit button" — two controls, not three. The
    25	   * clear was originally added on the belief that Figma's footer glyph was an ✕; Kiera
    26	   * confirmed (2026-08-20) it is the submit chevron, which `trailing` now carries.
    27	   *
    28	   * Kept as opt-in rather than deleted because a clear affordance is reasonable on a text
    29	   * input atom (a search field would want one) — it just should not be the atom's decision
    30	   * to impose. No consumer opts in today, so the footer renders one trailing control and
    31	   * matches Figma.
    32	   */
    33	  clearable?: boolean;
    34	  /**
    35	   * Trailing icon-button slot. This IS in the design system: it maps to the extracted
    36	   * TextfieldV2 spec's `trailing-icon` attribute (f2r/02-design/specs/components/text-input.md,
    37	   * Figma node 40000265:374). ZimmInputAction injects the submit chevron here — Kiera confirmed
    38	   * (2026-08-20) that the trailing glyph on the footer email field is the chevron, not an ✕.
    39	   * Renders after the clear button below, which is a separate, unspecified addition.
    40	   */
    41	  trailing?: React.ReactNode;
    42	  style?: CSSProperties;
    43	};
    44	
    45	/**
    46	 * Atom — flush text input with floating label. Mirrors zimm-text-input contract
    47	 * (flush + inverse variant).
    48	 *
    49	 * All styling lives in `theme/components/zimmTextInput.ts`. The component owns only the
    50	 * interaction state the theme cannot express: the value, focus, and whether the field is
    51	 * filled — `filled` and `focused` are fed back into the recipe so it can resolve the
    52	 * Figma colour cascade and the floated-label position.
    53	 */
    54	export const ZimmTextInput = ({
    55	  label,
    56	  type = 'text',
    57	  name,
    58	  inverse = false,
    59	  disabled = false,
    60	  helperText,
    61	  errorText,
    62	  onChange,
    63	  value: controlledValue,
    64	  defaultValue,
    65	  clearable = false,
    66	  trailing,
    67	  style,
    68	}: ZimmTextInputProps) => {
    69	  const inputId = useId();
    70	  const helperId = `${inputId}-helper`;
    71	  const errorId = `${inputId}-error`;
    72	  const hasError = !!errorText;
    73	
    74	  const { value, focused, inputRef, handleChange, handleClear, setFocused } = useZimmTextInputState({
    75	    onChange,
    76	    value: controlledValue,
    77	    defaultValue,
    78	  });
    79	
    80	  const styles = useMultiStyleConfig('ZimmTextInput', {
    81	    inverse,
    82	    disabled,
    83	    hasError,
    84	    focused,
    85	    filled: value.length > 0,
    86	  });
    87	
    88	  return (
    89	    <chakra.div __css={styles.root} style={style}>
    90	      <chakra.div __css={styles.row}>
    91	        {/* content — label + input stacked */}
    92	        <chakra.div __css={styles.content}>
    93	          <chakra.label htmlFor={inputId} __css={styles.label}>
    94	            {label}
    95	          </chakra.label>
    96	          <chakra.input
    97	            id={inputId}
    98	            ref={inputRef}
    99	            type={type}
   100	            name={name}
   101	            value={value}
   102	            disabled={disabled}
   103	            autoComplete={type === 'email' ? 'email' : undefined}
   104	            onChange={handleChange}
   105	            onFocus={() => setFocused(true)}
   106	            onBlur={() => setFocused(false)}
   107	            aria-invalid={hasError}
   108	            aria-describedby={[helperText && helperId, hasError && errorId].filter(Boolean).join(' ') || undefined}
   109	            __css={styles.input}
   110	          />
   111	        </chakra.div>
   112	        {/* Clear-✕ — opt-in only, see `clearable` above. Renders before {trailing}, so a
   113	            field that opts into both shows clear then trailing icon. */}
   114	        {clearable && !disabled && value.length > 0 && (
   115	          <chakra.button type="button" aria-label="Clear input" onClick={handleClear} __css={styles.clearButton}>
   116	            <ZimmIcon type="close" size="sm" aria-hidden={true} />
   117	          </chakra.button>
   118	        )}
   119	        {trailing}
   120	      </chakra.div>
   121	      {helperText && (
   122	        <chakra.p id={helperId} __css={styles.helper}>
   123	          {helperText}
   124	        </chakra.p>
   125	      )}
   126	      {errorText && (
   127	        <chakra.p id={errorId} role="alert" __css={styles.error}>
   128	          {errorText}
   129	        </chakra.p>
   130	      )}
   131	    </chakra.div>
   132	  );
   133	};
