L25:    </div>
L26:  ),
L27:  // Asserts leavesTheSite's scheme branch. Security-adjacent: rel="noopener noreferrer" is what
L28:  // stops the storefront URL reaching WhatsApp in the Referer header, and the accessible-name
L29:  // suffix is WCAG 3.2.5. Nothing else in CI covered this — the behaviour was only ever verified
L30:  // by hand, which is exactly the kind of gap that survives a refactor invisibly.
L31:  play: async ({ canvasElement }) => {
L32:    const canvas = within(canvasElement);
L33:
L34:    // http(s) → new tab, hardened, and the name says so
L35:    const whatsApp = canvas.getByRole('link', { name: /whatsapp/i });
L36:    await expect(whatsApp).toHaveAttribute('target', '_blank');
L37:    await expect(whatsApp).toHaveAttribute('rel', 'noopener noreferrer');
L38:    await expect(whatsApp).toHaveAccessibleName(/opens in a new tab/i);
L39:
L40:    // tel:/mailto: hand off to the OS — a target would do nothing, so there must not be one
L41:    for (const name of [/call us/i, /email us/i]) {
L42:      const link = canvas.getByRole('link', { name });
L43:      await expect(link).not.toHaveAttribute('target');
L44:      await expect(link).not.toHaveAccessibleName(/opens in a new tab/i);
L45:    }
L46:  },
L47:};
L48:
