===== footer/index.stories.tsx (165-206) =====
L165 };
L166 
L167 /**
L168  * The path SFCC-55 actually ships. Its AC scopes the Stay in Touch section to "an email input
L169  * field and submit button as a placeholder component" and defers the Omneo sign-up, so a valid
L170  * email resolves straight to the placeholder message with no name-capture modal.
L171  */
L172 export const SubscribePlaceholder: Story = {
L173   name: 'Subscribe — placeholder path (SFCC-55 default)',
L174   render: (args) => (
L175     <div style={{ width: '100%' }}>
L176       <Footer {...args} />
L177     </div>
L178   ),
L179   play: async ({ canvasElement }) => {
L180     const canvas = within(canvasElement);
L181     const footer = canvasElement.querySelector('footer[role="contentinfo"]') as HTMLElement;
L182     const slot = footer.querySelector('[aria-live]') as HTMLElement;
L183     const heightBefore = footer.getBoundingClientRect().height;
L184     const slotBefore = slot.getBoundingClientRect().height;
L185 
L186     await userEvent.type(canvas.getByRole('textbox', { name: /email/i }), 'test@example.com');
L187     await userEvent.click(canvas.getByRole('button', { name: /subscribe/i }));
L188 
L189     // No modal — the default build does not collect names (HPC-035 is a separate story with no
L190     // design yet). Queried against document.body because the modal would portal outside canvas.
L191     await expect(within(document.body).queryByRole('dialog')).not.toBeInTheDocument();
L192 
L193     // The shopper still gets honest feedback rather than a false success.
L194     await expect(canvas.getByText(/temporarily unavailable/i)).toBeInTheDocument();
L195     await expect(canvas.queryByText(/on the list/i)).not.toBeInTheDocument();
L196 
L197     // No layout shift. The field and the message are different heights (45px vs 36px of text),
L198     // so without subscribeControl's minHeight reservation the column re-flows — measurably at
L199     // every viewport, and visibly on mobile where the columns stack and the footer itself moves.
L200     // Asserted on the slot as well as the footer: at desktop widths the taller site-map column
L201     // sets the row height, so a footer-only check passes even when the column has shifted.
L202     const rounded = (n: number) => Math.round(n * 10) / 10;
L203     await expect(rounded(slot.getBoundingClientRect().height)).toBe(rounded(slotBefore));
L204     await expect(rounded(footer.getBoundingClientRect().height)).toBe(rounded(heightBefore));
L205   },
L206 };

